#include "emu.h"
#include <stdlib.h>
#include <string.h>
const char *disasm_sym_for(uint32_t pc){(void)pc;return "";}
static unsigned hash(const void *p,size_t n){const unsigned char *b=p;unsigned h=2166136261u;while(n--)h=(h^*b++)*16777619u;return h;}
static unsigned long long irq_count(Emu *e){unsigned long long n=0;for(int i=0;i<80;i++)n+=e->irq_taken[i];return n;}
int main(int argc,char **argv){if(argc<3)return 2;Emu *e=calloc(1,sizeof *e);e->dev=*device_find("ps");e->cmu.osc3_hz=e->dev.osc3_hz;e->rom=malloc(e->dev.rom_size);FILE *f=fopen(argv[1],"rb");if(!f)return 3;if(fread(e->rom,1,e->dev.rom_size,f)!=e->dev.rom_size)return 4;fclose(f);cpu_reset(e);unsigned long long target=strtoull(argv[2],0,10);unsigned next=1;unsigned edge=0,edge_count=0;uint64_t times[128];unsigned masks[128];if(argc>4){char *copy=_strdup(argv[4]);for(char *t=strtok(copy,",");t&&edge_count<128;t=strtok(NULL,",")){char *colon=strchr(t,':');if(!colon)return 7;*colon=0;times[edge_count]=(uint64_t)(strtod(t,NULL)*18432000.0);masks[edge_count++]=(unsigned)strtoul(colon+1,NULL,10);}free(copy);}while(e->cycles<target&&!e->stopped){if(edge<edge_count&&e->cycles>=times[edge]){periph_buttons(e,(uint8_t)masks[edge++]);}cpu_step(e);if(e->cycles-e->last_tick>=256){periph_tick(e,(uint32_t)(e->cycles-e->last_tick));e->last_tick=e->cycles;}if(e->cycles>=next*18432000ull){printf("%u pc=%08x cycles=%llu ram=%08x io=%08x gram=%08x irqs=%llu lcd=%llu tone=%u\n",next,e->pc,(unsigned long long)e->cycles,hash(e->a0ram,e->dev.a0ram_size),hash(e->ioram,e->dev.io_size),hash(e->lcd.gram,sizeof e->lcd.gram),irq_count(e),(unsigned long long)e->lcd.cmd_count,e->tone_ev_w);next++;}}
if(argc>3){unsigned pixels[PANEL_W*PANEL_H];int w,h;lcd_render(e,pixels,&w,&h);f=fopen(argv[3],"wb");if(!f)return 5;fprintf(f,"P6\n%d %d\n255\n",w,h);for(int i=0;i<w*h;i++){fputc(pixels[i]>>16,f);fputc(pixels[i]>>8,f);fputc(pixels[i],f);}fclose(f);}if(argc>3){char name[4096];if(strlen(argv[3])+7>=sizeof name)return 8;snprintf(name,sizeof name,"%s.tones",argv[3]);f=fopen(name,"w");if(!f)return 9;for(unsigned i=0;i<e->tone_ev_w&&i<TONE_EV_N;i++)fprintf(f,"%llu %.9g %u\n",(unsigned long long)e->tone_ev[i].cyc,e->tone_ev[i].freq,e->tone_ev[i].on);fclose(f);}return e->stopped?6:0;}
